import sys;sys.path.insert(0,'/opt/tools')
import rcb_aloha as ra, numpy as np, mujoco
s=ra.Session('/app/instance.json'); m=s.model;d=s.data
for label in ['home','picked','transferred']:
 mujoco.mj_resetDataKeyframe(m,d,m.key(label).id)
 if label=='home': d.qpos[s._box_q:s._box_q+2]+=s.box_xy
 mujoco.mj_forward(m,d)
 print(label,'box',d.xpos[s._box],'q',d.qpos[:16]);
 for n in ('left/gripper','right/gripper','left/left_finger','left/right_finger','right/left_finger','right/right_finger'):
  a=m.site(n).id; print(n,d.site_xpos[a], 'axis',d.site_xmat[a].reshape(3,3)[:,0])
print('limits',s.lower,s.upper)
